def quantile(values,q=.95):return float(np.quantile(values,q)) if values else None
def fmt(v):return '—' if v is None else f'{v:.3f}' if isinstance(v,float) else str(v)
def table(head,data):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(c))+'</th>' for c in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(fmt(c))+'</td>' for c in row)+'</tr>' for row in data)+'</tbody></table>'
def para(t):return '<p>'+t+'</p>'
def image(name):return '<img src="docs/hw11/'+name+'.png" alt="'+name+'">'
def summary(folder):
 out=[]
 for p in sorted(folder.glob('*/summary.json')):
  r=[]
  for f in p.parent.glob('client-*.jsonl'):r.extend(rows(f))
  if not r:continue
  cfg=read(p.parent/'config.json');ok=[x for x in r if x['outcome']=='completed'];errors=collections.Counter(x['outcome'] for x in r)
  out.append(dict(name=p.parent.name,config=cfg,rows=r,n=len(r),ok=len(ok),outcomes=dict(errors),p50=quantile([x['ttfc_seconds'] for x in ok],.5),p95=quantile([x['ttfc_seconds'] for x in ok]),duration_p95=quantile([x['duration_seconds'] for x in ok]),send_lag_p95=quantile([x['send_lag_seconds'] for x in r]),send_lag_max=max(x['send_lag_seconds'] for x in r),clock_offset_span=max(x['sent_wall']-x['sent_mono'] for x in r)-min(x['sent_wall']-x['sent_mono'] for x in r),queue_mean=statistics.mean(x['queue_seconds'] for x in ok) if ok else None))
 return out
