 if not selected:continue
 ys=[r['p95'] for r in selected];ax.scatter([i]*len(ys),ys,color={'ordinary':'#487696','sticky':'#b77046','fixed':'#4e8368'}[policy],s=55);ax.plot([i-.15,i+.15],[statistics.mean(ys)]*2,color='#27334a');positions.append(i);labels.append(traffic+'\n'+policy)
