 ready=[v if 'pods' in r else float('nan') for r,v in zip(scale,ready)]
 axes[0].step(times,current,label='HPA current',where='post');axes[0].step(times,desired,label='HPA desired',where='post');axes[0].step(times,ready,label='Ready',where='post');axes[0].set_ylabel('реплики');axes[0].set_yticks([2,3]);axes[0].legend(ncol=3)
 rr=[r for run in autoscale for r in run['rows']];edges=np.arange(0,times[-1]+15,10);hist,_=np.histogram([r['sent_wall']-origin for r in rr],edges);axes[1].stairs(hist/10,edges);axes[1].set_ylabel('отправлено /с')
 for alert,label in [('PlannerLatency','задержка'),('PlannerRejects','отказы')]:
  states=[]
